from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Optional

from secretscan.rules.entropy import shannon_entropy


@dataclass
class Rule:
    id: str = ""
    description: str = ""
    regex: str = ""
    secret_group: int = 0
    keywords: list[str] = field(default_factory=list)
    entropy_enabled: bool = False
    entropy_min: float = 0.0
    severity: str = "low"
    tags: list[str] = field(default_factory=list)
    hash_scope: str = "value"

    def is_file_identity(self) -> bool:
        return self.hash_scope == "file"


@dataclass
class Match:
    secret: str = ""
    start: int = 0
    end: int = 0


class CompiledRule:
    def __init__(self, rule: Rule) -> None:
        if not rule.id:
            raise ValueError("rule has empty id")
        if not rule.regex:
            raise ValueError(f"rule {rule.id!r}: empty regex")
        self.rule = rule
        self._re = re.compile(rule.regex)
        self._lower_keywords = [k.lower() for k in rule.keywords]
        if rule.secret_group > self._re.groups:
            raise ValueError(
                f"rule {rule.id!r}: secret_group {rule.secret_group} "
                f"exceeds {self._re.groups} capture groups"
            )

    @property
    def id(self) -> str:
        return self.rule.id

    def quick_reject(self, lower_line: str) -> bool:
        if not self._lower_keywords:
            return False
        return not any(kw in lower_line for kw in self._lower_keywords)

    def find_all(self, line: str) -> list[Match]:
        matches: list[Match] = []
        for m in self._re.finditer(line):
            group = self.rule.secret_group
            if group > 0 and group <= len(m.groups()) and m.group(group) is not None:
                start, end = m.span(group)
            else:
                start, end = m.span(0)
            secret = line[start:end]
            if self.rule.entropy_enabled and shannon_entropy(secret) < self.rule.entropy_min:
                continue
            matches.append(Match(secret=secret, start=start, end=end))
        return matches
